action_input.code:
import json

with open('json/superpower.json', 'r') as f:
    data = json.load(f)

# Find Phoenix Force
for record in data['records']:
    if record['power_name'] == 'Phoenix Force':
        print(f"Power ID: {record['id']}, Power Name: {record['power_name']}")
        break
else:
    print("Phoenix Force not found")
